package com.highalchemytracker;

final class AlchemyCastTracker
{
	private static final int MAX_PENDING_TICKS = 5;

	private int pendingItemId = -1;
	private int pendingGrossGp;
	private int pendingTick = -1;
	private int lastMagicXp = -1;

	void setMagicXpBaseline(int magicXp)
	{
		lastMagicXp = magicXp;
	}

	void prepareCast(int itemId, int grossGp, int tick)
	{
		if (itemId < 0 || grossGp < 0)
		{
			return;
		}

		pendingItemId = itemId;
		pendingGrossGp = grossGp;
		pendingTick = tick;
	}

	CompletedCast onMagicXpChanged(int magicXp, int tick)
	{
		final int previousXp = lastMagicXp;
		lastMagicXp = magicXp;

		if (pendingItemId < 0 || previousXp >= magicXp || isExpired(tick))
		{
			return null;
		}

		final CompletedCast completedCast = new CompletedCast(pendingItemId, pendingGrossGp);
		clearPendingCast();
		return completedCast;
	}

	void expirePendingCast(int tick)
	{
		if (pendingItemId >= 0 && isExpired(tick))
		{
			clearPendingCast();
		}
	}

	void reset()
	{
		clearPendingCast();
		lastMagicXp = -1;
	}

	private boolean isExpired(int tick)
	{
		return tick < pendingTick || tick - pendingTick > MAX_PENDING_TICKS;
	}

	private void clearPendingCast()
	{
		pendingItemId = -1;
		pendingGrossGp = 0;
		pendingTick = -1;
	}

	static final class CompletedCast
	{
		private final int itemId;
		private final int grossGp;

		private CompletedCast(int itemId, int grossGp)
		{
			this.itemId = itemId;
			this.grossGp = grossGp;
		}

		int getItemId()
		{
			return itemId;
		}

		int getGrossGp()
		{
			return grossGp;
		}
	}
}

package com.highalchemytracker;

final class AlchemyRecord
{
	private long casts;
	private long grossGp;

	AlchemyRecord()
	{
	}

	AlchemyRecord(long casts, long grossGp)
	{
		this.casts = casts;
		this.grossGp = grossGp;
	}

	long getCasts()
	{
		return casts;
	}

	long getGrossGp()
	{
		return grossGp;
	}

	void addCast(long gp)
	{
		casts++;
		grossGp += gp;
	}
}

package com.highalchemytracker;

final class AlchemyRecordCodec
{
	private static final String VERSION = "1";
	private static final String SEPARATOR = ":";

	private AlchemyRecordCodec()
	{
	}

	static String encode(AlchemyRecord record)
	{
		return VERSION + SEPARATOR + record.getCasts() + SEPARATOR + record.getGrossGp();
	}

	static AlchemyRecord decode(String value)
	{
		if (value == null)
		{
			return null;
		}

		final String[] parts = value.split(SEPARATOR, -1);
		if (parts.length != 3 || !VERSION.equals(parts[0]))
		{
			return null;
		}

		try
		{
			final long casts = Long.parseLong(parts[1]);
			final long grossGp = Long.parseLong(parts[2]);
			if (casts < 0 || grossGp < 0)
			{
				return null;
			}
			return new AlchemyRecord(casts, grossGp);
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.highalchemytracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

final class HighAlchemyTrackerPanel extends PluginPanel
{
	private final Runnable resetAction;
	private final JLabel lifetimeCasts = valueLabel();
	private final JLabel lifetimeGp = valueLabel();
	private final JLabel sessionCasts = valueLabel();
	private final JLabel sessionGp = valueLabel();
	private final JPanel itemList = new JPanel();

	HighAlchemyTrackerPanel(Runnable resetAction)
	{
		this.resetAction = resetAction;

		final JLabel title = new JLabel("High Alchemy Tracker");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setHorizontalAlignment(SwingConstants.CENTER);
		title.setBorder(BorderFactory.createEmptyBorder(2, 0, 5, 0));
		add(title);

		add(section("Lifetime", lifetimeCasts, lifetimeGp));
		add(section("This session", sessionCasts, sessionGp));

		final JLabel itemsTitle = new JLabel("Items");
		itemsTitle.setFont(FontManager.getRunescapeBoldFont());
		itemsTitle.setForeground(Color.WHITE);
		itemsTitle.setBorder(BorderFactory.createEmptyBorder(6, 2, 2, 2));
		add(itemsTitle);

		itemList.setLayout(new BoxLayout(itemList, BoxLayout.Y_AXIS));
		itemList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(itemList);

		final JButton resetButton = new JButton("Reset all totals");
		resetButton.setFocusable(false);
		resetButton.addActionListener(event -> confirmReset());
		add(resetButton);
	}

	void update(TrackerSnapshot snapshot)
	{
		lifetimeCasts.setText(format(snapshot.getLifetimeCasts()));
		lifetimeGp.setText(format(snapshot.getLifetimeGrossGp()) + " gp");
		sessionCasts.setText(format(snapshot.getSessionCasts()));
		sessionGp.setText(format(snapshot.getSessionGrossGp()) + " gp");

		itemList.removeAll();
		if (snapshot.getItems().isEmpty())
		{
			final JLabel empty = new JLabel("No completed casts yet.");
			empty.setForeground(Color.GRAY);
			empty.setAlignmentX(Component.LEFT_ALIGNMENT);
			empty.setBorder(BorderFactory.createEmptyBorder(5, 2, 5, 2));
			itemList.add(empty);
		}
		else
		{
			for (TrackerSnapshot.ItemRow item : snapshot.getItems())
			{
				itemList.add(itemRow(item));
				itemList.add(Box.createRigidArea(new Dimension(0, 3)));
			}
		}

		itemList.revalidate();
		itemList.repaint();
	}

	private JPanel section(String heading, JLabel casts, JLabel gp)
	{
		final JPanel panel = new JPanel(new BorderLayout(0, 4));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(6, 7, 6, 7));

		final JLabel headingLabel = new JLabel(heading);
		headingLabel.setFont(FontManager.getRunescapeBoldFont());
		headingLabel.setForeground(Color.WHITE);
		panel.add(headingLabel, BorderLayout.NORTH);

		final JPanel values = new JPanel(new GridLayout(2, 2, 4, 2));
		values.setOpaque(false);
		values.add(caption("Casts"));
		values.add(casts);
		values.add(caption("Gross GP"));
		values.add(gp);
		panel.add(values, BorderLayout.CENTER);
		return panel;
	}

	private JPanel itemRow(TrackerSnapshot.ItemRow item)
	{
		final JPanel row = new JPanel(new BorderLayout(4, 2));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(6, 7, 6, 7));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel name = new JLabel(item.getName());
		name.setForeground(Color.WHITE);
		row.add(name, BorderLayout.NORTH);

		final JLabel details = new JLabel(format(item.getCasts()) + " casts  •  "
			+ format(item.getGrossGp()) + " gp");
		details.setForeground(Color.LIGHT_GRAY);
		row.add(details, BorderLayout.CENTER);
		return row;
	}

	private void confirmReset()
	{
		final int choice = JOptionPane.showConfirmDialog(
			this,
			"Delete all lifetime and session High Alchemy totals for this character?",
			"Reset High Alchemy Tracker",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE);

		if (choice == JOptionPane.YES_OPTION)
		{
			resetAction.run();
		}
	}

	private static JLabel caption(String text)
	{
		final JLabel label = new JLabel(text);
		label.setForeground(Color.LIGHT_GRAY);
		return label;
	}

	private static JLabel valueLabel()
	{
		final JLabel label = new JLabel("0", SwingConstants.RIGHT);
		label.setForeground(Color.WHITE);
		return label;
	}

	private static String format(long value)
	{
		return String.format(Locale.US, "%,d", value);
	}
}

package com.highalchemytracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "High Alchemy Tracker",
	description = "Tracks successful High Level Alchemy casts and the gross GP they create.",
	tags = {"alch", "alchemy", "gp", "magic", "tracker"}
)
public class HighAlchemyTrackerPlugin extends Plugin
{
	static final String CONFIG_GROUP = "high-alchemy-tracker";
	static final String ITEM_KEY_PREFIX = "item_";

	private static final String ALCH_TARGET = "High Level Alchemy";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	private final Map<Integer, AlchemyRecord> records = new HashMap<>();
	private final AlchemyCastTracker castTracker = new AlchemyCastTracker();

	private long sessionCasts;
	private long sessionGrossGp;
	private HighAlchemyTrackerPanel panel;
	private NavigationButton navigationButton;

	@Override
	protected void startUp()
	{
		panel = new HighAlchemyTrackerPanel(() -> clientThread.invoke(this::resetTotals));
		navigationButton = NavigationButton.builder()
			.tooltip("High Alchemy Tracker")
			.icon(createNavigationIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);

		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				castTracker.setMagicXpBaseline(client.getSkillExperience(Skill.MAGIC));
			}
			loadRecords();
		});
	}

	@Override
	protected void shutDown()
	{
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}

		records.clear();
		castTracker.reset();
		sessionCasts = 0;
		sessionGrossGp = 0;
		panel = null;
		navigationButton = null;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		final String option = event.getMenuOption();
		final String target = event.getMenuTarget();
		if (!"Cast".equals(option) || target == null || !target.contains(ALCH_TARGET))
		{
			return;
		}

		int itemId = event.getItemId();
		if (itemId < 0)
		{
			final Widget parent = client.getWidget(event.getParam1());
			final int slot = event.getParam0();
			if (parent != null && slot >= 0)
			{
				final Widget child = parent.getChild(slot);
				if (child != null)
				{
					itemId = child.getItemId();
				}
			}
		}

		if (itemId < 0)
		{
			return;
		}

		final int canonicalItemId = itemManager.canonicalize(itemId);
		final ItemComposition item = itemManager.getItemComposition(canonicalItemId);
		if (item == null)
		{
			return;
		}

		castTracker.prepareCast(canonicalItemId, item.getHaPrice(), client.getTickCount());
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.MAGIC)
		{
			return;
		}

		final AlchemyCastTracker.CompletedCast completedCast =
			castTracker.onMagicXpChanged(event.getXp(), client.getTickCount());
		if (completedCast != null)
		{
			recordCast(completedCast.getItemId(), completedCast.getGrossGp());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		castTracker.expirePendingCast(client.getTickCount());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			castTracker.setMagicXpBaseline(client.getSkillExperience(Skill.MAGIC));
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			castTracker.reset();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		sessionCasts = 0;
		sessionGrossGp = 0;
		castTracker.reset();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			castTracker.setMagicXpBaseline(client.getSkillExperience(Skill.MAGIC));
		}
		loadRecords();
	}

	private void recordCast(int itemId, int grossGp)
	{
		final AlchemyRecord record = records.computeIfAbsent(itemId, ignored -> new AlchemyRecord());
		record.addCast(grossGp);
		sessionCasts++;
		sessionGrossGp += grossGp;

		configManager.setRSProfileConfiguration(
			CONFIG_GROUP,
			ITEM_KEY_PREFIX + itemId,
			AlchemyRecordCodec.encode(record));
		refreshPanel();
	}

	private void loadRecords()
	{
		records.clear();
		final String profile = configManager.getRSProfileKey();
		if (profile != null)
		{
			for (String key : configManager.getRSProfileConfigurationKeys(CONFIG_GROUP, profile, ITEM_KEY_PREFIX))
			{
				final int itemId;
				try
				{
					itemId = Integer.parseInt(key.substring(ITEM_KEY_PREFIX.length()));
				}
				catch (NumberFormatException ex)
				{
					log.debug("Ignoring invalid High Alchemy Tracker key: {}", key);
					continue;
				}

				final String value = configManager.getRSProfileConfiguration(CONFIG_GROUP, key);
				final AlchemyRecord record = AlchemyRecordCodec.decode(value);
				if (record != null)
				{
					records.put(itemId, record);
				}
			}
		}
		refreshPanel();
	}

	private void resetTotals()
	{
		final String profile = configManager.getRSProfileKey();
		if (profile != null)
		{
			for (String key : configManager.getRSProfileConfigurationKeys(CONFIG_GROUP, profile, ITEM_KEY_PREFIX))
			{
				configManager.unsetRSProfileConfiguration(CONFIG_GROUP, key);
			}
		}

		records.clear();
		sessionCasts = 0;
		sessionGrossGp = 0;
		refreshPanel();
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}

		long lifetimeCasts = 0;
		long lifetimeGrossGp = 0;
		final List<TrackerSnapshot.ItemRow> items = new ArrayList<>();
		for (Map.Entry<Integer, AlchemyRecord> entry : records.entrySet())
		{
			final AlchemyRecord record = entry.getValue();
			lifetimeCasts += record.getCasts();
			lifetimeGrossGp += record.getGrossGp();

			final ItemComposition item = itemManager.getItemComposition(entry.getKey());
			final String name = item == null ? "Item " + entry.getKey() : item.getName();
			items.add(new TrackerSnapshot.ItemRow(name, record.getCasts(), record.getGrossGp()));
		}

		items.sort(Comparator.comparingLong(TrackerSnapshot.ItemRow::getGrossGp).reversed()
			.thenComparing(TrackerSnapshot.ItemRow::getName));
		final TrackerSnapshot snapshot = new TrackerSnapshot(
			lifetimeCasts,
			lifetimeGrossGp,
			sessionCasts,
			sessionGrossGp,
			items);
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.update(snapshot);
			}
		});
	}

	private static BufferedImage createNavigationIcon()
	{
		final BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(244, 196, 48));
		graphics.fillOval(2, 3, 11, 11);
		graphics.setColor(new Color(157, 105, 20));
		graphics.setStroke(new BasicStroke(1.2f));
		graphics.drawOval(2, 3, 11, 11);
		graphics.setColor(new Color(255, 244, 166));
		graphics.drawLine(7, 5, 7, 11);
		graphics.drawLine(5, 8, 9, 8);
		graphics.setColor(Color.WHITE);
		graphics.drawLine(12, 1, 12, 5);
		graphics.drawLine(10, 3, 14, 3);
		graphics.dispose();
		return image;
	}
}

package com.highalchemytracker;

import java.util.Collections;
import java.util.List;

final class TrackerSnapshot
{
	private final long lifetimeCasts;
	private final long lifetimeGrossGp;
	private final long sessionCasts;
	private final long sessionGrossGp;
	private final List<ItemRow> items;

	TrackerSnapshot(long lifetimeCasts, long lifetimeGrossGp, long sessionCasts,
		long sessionGrossGp, List<ItemRow> items)
	{
		this.lifetimeCasts = lifetimeCasts;
		this.lifetimeGrossGp = lifetimeGrossGp;
		this.sessionCasts = sessionCasts;
		this.sessionGrossGp = sessionGrossGp;
		this.items = Collections.unmodifiableList(items);
	}

	long getLifetimeCasts()
	{
		return lifetimeCasts;
	}

	long getLifetimeGrossGp()
	{
		return lifetimeGrossGp;
	}

	long getSessionCasts()
	{
		return sessionCasts;
	}

	long getSessionGrossGp()
	{
		return sessionGrossGp;
	}

	List<ItemRow> getItems()
	{
		return items;
	}

	static final class ItemRow
	{
		private final String name;
		private final long casts;
		private final long grossGp;

		ItemRow(String name, long casts, long grossGp)
		{
			this.name = name;
			this.casts = casts;
			this.grossGp = grossGp;
		}

		String getName()
		{
			return name;
		}

		long getCasts()
		{
			return casts;
		}

		long getGrossGp()
		{
			return grossGp;
		}
	}
}

package com.highalchemytracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertNotNull;

public class AlchemyCastTrackerTest
{
	@Test
	public void recordsPreparedCastOnMagicXpGain()
	{
		final AlchemyCastTracker tracker = new AlchemyCastTracker();
		tracker.setMagicXpBaseline(10_000);
		tracker.prepareCast(2, 120, 50);

		final AlchemyCastTracker.CompletedCast cast = tracker.onMagicXpChanged(10_065, 51);

		assertNotNull(cast);
		assertEquals(2, cast.getItemId());
		assertEquals(120, cast.getGrossGp());
	}

	@Test
	public void ignoresPreparedCastWithoutXpGain()
	{
		final AlchemyCastTracker tracker = new AlchemyCastTracker();
		tracker.setMagicXpBaseline(10_000);
		tracker.prepareCast(2, 120, 50);

		assertNull(tracker.onMagicXpChanged(10_000, 51));
	}

	@Test
	public void doesNotCountOneCastTwice()
	{
		final AlchemyCastTracker tracker = new AlchemyCastTracker();
		tracker.setMagicXpBaseline(10_000);
		tracker.prepareCast(2, 120, 50);

		assertNotNull(tracker.onMagicXpChanged(10_065, 51));
		assertNull(tracker.onMagicXpChanged(10_130, 52));
	}

	@Test
	public void expiresOldPreparedCast()
	{
		final AlchemyCastTracker tracker = new AlchemyCastTracker();
		tracker.setMagicXpBaseline(10_000);
		tracker.prepareCast(2, 120, 50);
		tracker.expirePendingCast(56);

		assertNull(tracker.onMagicXpChanged(10_065, 56));
	}

	@Test
	public void acceptsExperienceMultipliers()
	{
		final AlchemyCastTracker tracker = new AlchemyCastTracker();
		tracker.setMagicXpBaseline(10_000);
		tracker.prepareCast(2, 120, 50);

		assertNotNull(tracker.onMagicXpChanged(10_325, 51));
	}
}

package com.highalchemytracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class AlchemyRecordCodecTest
{
	@Test
	public void roundTripsRecord()
	{
		final AlchemyRecord decoded = AlchemyRecordCodec.decode(
			AlchemyRecordCodec.encode(new AlchemyRecord(42, 123_456)));

		assertEquals(42, decoded.getCasts());
		assertEquals(123_456, decoded.getGrossGp());
	}

	@Test
	public void rejectsUnknownVersion()
	{
		assertNull(AlchemyRecordCodec.decode("2:42:123456"));
	}

	@Test
	public void rejectsNegativeValues()
	{
		assertNull(AlchemyRecordCodec.decode("1:-1:100"));
		assertNull(AlchemyRecordCodec.decode("1:1:-100"));
	}

	@Test
	public void rejectsMalformedValue()
	{
		assertNull(AlchemyRecordCodec.decode(null));
		assertNull(AlchemyRecordCodec.decode("not-a-record"));
		assertNull(AlchemyRecordCodec.decode("1:casts:gp"));
	}
}

